package com.careerpilot.modules.jobmatch.mapper;import com.careerpilot.modules.jobmatch.dto.*;import com.careerpilot.modules.jobmatch.entity.*;import org.springframework.stereotype.Component;import java.util.*;
@Component public class JobMatchMapper{public static final String DISCLAIMER="CareerPilot match scores are application heuristics and are not official recruiter or ATS vendor scores.";public JobMatchSummaryResponse summary(JobMatch m){return new JobMatchSummaryResponse(m.getId(),m.getResume().getId(),m.getJobTitle(),m.getCompanyName(),m.getOverallMatchScore(),m.getCreatedAt());}public JobMatchResponse detail(JobMatch m){List<JobMatchSkillResponse>all=m.getSkills().stream().map(s->new JobMatchSkillResponse(s.getSkillName(),s.getNormalizedSkillName(),s.getMatchStatus(),s.getImportance(),s.getPriority(),s.getSource(),s.getEvidence(),s.getRecommendation())).toList();return new JobMatchResponse(m.getId(),m.getResume().getId(),m.getJobTitle(),m.getCompanyName(),m.getOverallMatchScore(),m.getKeywordMatchScore(),m.getSkillMatchScore(),m.getSemanticMatchScore(),m.getExperienceMatchScore(),m.getEducationMatchScore(),m.getSemanticStatus(),m.getExperienceStatus(),m.getEducationStatus(),m.getScoringVersion(),m.getCreatedAt(),filter(all,MatchStatus.MATCHED,false),filter(all,MatchStatus.PARTIAL,false),filter(all,MatchStatus.MISSING,false),filter(all,MatchStatus.MATCHED,true),DISCLAIMER);}private List<JobMatchSkillResponse>filter(List<JobMatchSkillResponse>all,MatchStatus status,boolean extra){return all.stream().filter(v->v.status()==status&&("RESUME_EXTRA".equals(v.source())==extra)).toList();}}
